#include <iostream>
#include <cstring>
#include <csignal>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <fcntl.h>
#include <errno.h>

// Distributed cache client for processing user-uploaded binary blobs
// Protocol: [4-byte len][payload][4-byte checksum]

static const int MAX_UPLOAD_SIZE = 1048576; // 1MB
static const int CACHE_PORT = 9734;

struct CacheEntry {
    char* data;
    size_t len;
    volatile int refcount;
};

// Global state for signal-safe cleanup
static CacheEntry* g_active_entry = nullptr;
static volatile sig_atomic_t g_shutdown_requested = 0;
static int g_cache_fd = -1;
static char g_log_buffer[512];
static volatile sig_atomic_t g_in_critical_section = 0;

void write_log(const char* msg) {
    int fd = open("/var/log/cache_client.log", O_WRONLY | O_APPEND | O_CREAT, 0640);
    if (fd >= 0) {
        write(fd, msg, strlen(msg));
        close(fd);
    }
}

void cleanup_entry(CacheEntry* entry) {
    if (entry && entry->data) {
        memset(entry->data, 0, entry->len);
        free(entry->data);
        entry->data = nullptr;
        entry->len = 0;
    }
    free(entry);
}

void sigterm_handler(int sig) {
    g_shutdown_requested = 1;

    // Attempt graceful cleanup of in-flight upload
    if (!g_in_critical_section && g_active_entry != nullptr) {
        // Log the interruption
        snprintf(g_log_buffer, sizeof(g_log_buffer),
                 "SIGTERM received, cleaning entry at %p (len=%zu)\n",
                 (void*)g_active_entry, g_active_entry->len);
        write_log(g_log_buffer);

        // Free the active entry to prevent memory leak
        cleanup_entry(g_active_entry);
        g_active_entry = nullptr;
    }

    if (g_cache_fd >= 0) {
        close(g_cache_fd);
        g_cache_fd = -1;
    }
}

void sigusr1_handler(int sig) {
    // Status dump - async signal safe (uses only write)
    const char* status = g_active_entry ? "PROCESSING\n" : "IDLE\n";
    write(STDOUT_FILENO, status, strlen(status));
}

int connect_to_cache(const char* host) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return -1;

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(CACHE_PORT);
    inet_pton(AF_INET, host, &addr.sin_addr);

    if (connect(fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

uint32_t compute_checksum(const char* data, size_t len) {
    uint32_t csum = 0;
    for (size_t i = 0; i < len; i++) {
        csum = ((csum << 5) + csum) + (unsigned char)data[i];
    }
    return csum;
}

int validate_upload(const char* buf, size_t total_len) {
    if (total_len < 8) return -1; // need at least header + checksum

    uint32_t payload_len;
    memcpy(&payload_len, buf, 4);
    payload_len = ntohl(payload_len);

    if (payload_len > MAX_UPLOAD_SIZE) return -1;
    if (payload_len + 8 != total_len) return -1;

    uint32_t expected_csum;
    memcpy(&expected_csum, buf + 4 + payload_len, 4);
    expected_csum = ntohl(expected_csum);

    uint32_t actual_csum = compute_checksum(buf + 4, payload_len);
    if (actual_csum != expected_csum) return -1;

    return 0;
}

int process_upload(const char* upload_buf, size_t upload_len) {
    if (validate_upload(upload_buf, upload_len) != 0) {
        write_log("Upload validation failed\n");
        return -1;
    }

    uint32_t payload_len;
    memcpy(&payload_len, upload_buf, 4);
    payload_len = ntohl(payload_len);

    // Allocate cache entry
    CacheEntry* entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    if (!entry) return -1;

    entry->data = (char*)malloc(payload_len);
    if (!entry->data) {
        free(entry);
        return -1;
    }
    entry->len = payload_len;
    entry->refcount = 1;

    // Set global pointer before copy (for cleanup on signal)
    g_active_entry = entry;

    // Copy payload data - this is the "critical" window
    // A signal here is fine since g_in_critical_section guards cleanup
    g_in_critical_section = 1;
    memcpy(entry->data, upload_buf + 4, payload_len);
    g_in_critical_section = 0;

    // Send to cache server
    if (g_cache_fd >= 0 && !g_shutdown_requested) {
        uint32_t net_len = htonl(payload_len);
        write(g_cache_fd, &net_len, 4);
        write(g_cache_fd, entry->data, payload_len);
    }

    // Entry is now committed; use-after-free possible if signal
    // fires between here and nulling the global
    cleanup_entry(entry);
    g_active_entry = nullptr;

    return 0;
}

int main(int argc, char* argv[]) {
    const char* cache_host = argc > 1 ? argv[1] : "127.0.0.1";

    // Install signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigterm_handler;
    sa.sa_flags = 0; // No SA_RESTART - allow interruption
    sigemptyset(&sa.sa_mask);
    sigaction(SIGTERM, &sa, nullptr);

    sa.sa_handler = sigusr1_handler;
    sigaction(SIGUSR1, &sa, nullptr);

    g_cache_fd = connect_to_cache(cache_host);
    if (g_cache_fd < 0) {
        write_log("Failed to connect to cache\n");
        return 1;
    }

    // Read uploads from stdin (e.g., piped from web server)
    char upload_buf[MAX_UPLOAD_SIZE + 8];

    while (!g_shutdown_requested) {
        uint32_t frame_len;
        ssize_t n = read(STDIN_FILENO, &frame_len, 4);
        if (n <= 0) break;

        frame_len = ntohl(frame_len);
        if (frame_len > sizeof(upload_buf)) {
            write_log("Frame too large\n");
            continue;
        }

        // Store length header in buffer for validation
        uint32_t net_frame = htonl(frame_len - 4);
        memcpy(upload_buf, &net_frame, 4);

        size_t total_read = 0;
        while (total_read < frame_len - 4) {
            n = read(STDIN_FILENO, upload_buf + 4 + total_read, frame_len - 4 - total_read);
            if (n <= 0) break;
            total_read += n;
        }

        if (total_read == frame_len - 4) {
            process_upload(upload_buf, frame_len);
        }
    }

    if (g_cache_fd >= 0) close(g_cache_fd);
    return 0;
}
